pub struct PlaceArgs {
    pub reference: HoldReference,
    pub subject: Subject,
    pub reason: HoldReason,
}

pub fn dispatch_place(
    repo: &mut impl crate::kernel::Repository<Hold>,
    route: Option<&crate::kernel::RoutingEnvelope>,
    args: PlaceArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Hold> {
    args.reference.check_invariants()?;
    args.subject.check_invariants()?;
    args.reason.check_invariants()?;
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, HOLD_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
            Some(__route) => {
                __route.require_depth(0)?;
                let __hydrate_id: String = args.reference.value.to_string();
                if __route.aggregate() != __hydrate_id.as_str() {
                    return Err(crate::kernel::Refusal::TypeMismatch(format!(
                        "Place routes to {:?}, but its identity facts name {:?}",
                        __route.aggregate(),
                        __hydrate_id
                    )));
                }
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Hold {
                        reference: Some(args.reference.clone()),
                        subject: Some(args.subject.clone()),
                        reason: Some(args.reason.clone()),
                        status: "placed".to_string(),
                    }),
                    state_independent: true,
                }
            }
            None => {
                let __hydrate_id: String = args.reference.value.to_string();
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Hold {
                        reference: Some(args.reference.clone()),
                        subject: Some(args.subject.clone()),
                        reason: Some(args.reason.clone()),
                        status: "placed".to_string(),
                    }),
                    state_independent: true,
                }
            }
        },
        "Place",
        "Banking::Hold",
        "Hold",
        "reference.value",
        &with_references,
        &[],
        None,
        |record| {
            record.reference = Some(args.reference.clone());
            record.subject = Some(args.subject.clone());
            record.reason = Some(args.reason.clone());
            Ok(())
        },
        &[],
        &hold_invariants(),
        &["HoldPlaced"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

